import { test, expect } from "@playwright/test";

// TC-001: Locked-out user cannot log in
test.describe("TC-001: Locked-out user cannot log in", () => {
  test("shows locked-out error and stays on login page", async ({ page }) => {
    const username = "locked_out_user";
    const password = "secret_sauce";
    const expectedError = "Epic sadface: Sorry, this user has been locked out.";

    // Precondition: application is open on the login page
    await page.goto("/");
    await expect(page.locator('[data-test="login-button"]')).toBeVisible();

    // Step 1: Enter username
    const usernameField = page.locator('[data-test="username"]');
    await usernameField.fill(username);
    await expect(usernameField).toHaveValue(username);

    // Step 2: Enter password (masked)
    const passwordField = page.locator('[data-test="password"]');
    await passwordField.fill(password);
    await expect(passwordField).toHaveValue(password);
    await expect(passwordField).toHaveAttribute("type", "password");

    // Step 3: Click Login and expect locked-out error
    await page.locator('[data-test="login-button"]').click();
    const errorMessage = page.locator('[data-test="error"]');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveText(expectedError);

    // Step 4: User stays on the login page; inventory is not shown
    await expect(page).not.toHaveURL(/inventory/);
    await expect(page.locator('[data-test="login-button"]')).toBeVisible();
    await expect(page.locator('[data-test="title"]')).toHaveCount(0);
  });
});

