import { test, expect } from "@playwright/test";

import { loginAs } from "../support/auth";

test.describe("TC-003: Sort products by price, low to high", () => {
  test("products are sorted by price ascending with expected first and last items", async ({ page }) => {
    await loginAs(page, "standard_user");

    const sortDropdown = page.locator('[data-test="product-sort-container"]');
    await sortDropdown.selectOption({ label: "Price (low to high)" });
    await expect(sortDropdown.locator("option:checked")).toHaveText("Price (low to high)");

    const priceTexts = await page.locator('[data-test="inventory-item-price"]').allTextContents();
    const prices = priceTexts.map((text) => Number(text.replace("$", "")));
    expect(prices.length).toBeGreaterThan(0);
    const sortedPrices = [...prices].sort((a, b) => a - b);
    expect(prices).toEqual(sortedPrices);

    const names = page.locator('[data-test="inventory-item-name"]');
    await expect(names.first()).toHaveText("Sauce Labs Onesie");
    await expect(names.last()).toHaveText("Sauce Labs Fleece Jacket");
    await expect(page.locator('[data-test="inventory-item-price"]').first()).toHaveText("$7.99");
    await expect(page.locator('[data-test="inventory-item-price"]').last()).toHaveText("$49.99");
  });
});

