import { test, expect } from "@playwright/test";

import { loginAs } from "../support/auth";

test.describe("TC-004: Checkout validates required fields and completes the order", () => {
  test("should validate required fields and complete the order", async ({ page }) => {
    await loginAs(page, "standard_user");

    // Precondition: "Sauce Labs Backpack" is in the cart
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    await expect(page.locator('[data-test="shopping-cart-badge"]')).toHaveText("1");

    // Step 1: Open the cart and click Checkout
    await page.locator('[data-test="shopping-cart-link"]').click();
    await page.locator('[data-test="checkout"]').click();
    await expect(page.locator('[data-test="title"]')).toHaveText("Checkout: Your Information");

    // Step 2: Leave all fields empty and click Continue
    await page.locator('[data-test="continue"]').click();
    await expect(page.locator('[data-test="error"]')).toHaveText("Error: First Name is required");

    // Step 3: Fill First Name only and click Continue
    await page.locator('[data-test="firstName"]').fill("John");
    await page.locator('[data-test="continue"]').click();
    await expect(page.locator('[data-test="error"]')).toHaveText("Error: Last Name is required");

    // Step 4: Fill Last Name only and click Continue
    await page.locator('[data-test="lastName"]').fill("Doe");
    await page.locator('[data-test="continue"]').click();
    await expect(page.locator('[data-test="error"]')).toHaveText("Error: Postal Code is required");

    // Step 5: Fill Postal Code and click Continue
    await page.locator('[data-test="postalCode"]').fill("12345");
    await page.locator('[data-test="continue"]').click();
    await expect(page.locator('[data-test="title"]')).toHaveText("Checkout: Overview");
    await expect(page.locator('[data-test="inventory-item"]')).toHaveCount(1);
    await expect(page.locator('[data-test="inventory-item-name"]')).toHaveText("Sauce Labs Backpack");
    await expect(page.locator('[data-test="inventory-item-price"]')).toHaveText("$29.99");

    // Step 6: Click Finish
    await page.locator('[data-test="finish"]').click();
    await expect(page.locator('[data-test="complete-header"]')).toHaveText("Thank you for your order!");

    // Step 7: Cart badge is no longer shown
    await expect(page.locator('[data-test="shopping-cart-badge"]')).toHaveCount(0);
  });
});

