import { test, expect } from "@playwright/test";

import { loginAs } from "../support/auth";

test.describe("TC-005", () => {
  test("Checkout overview shows the correct price summary", async ({ page }) => {
    // Precondition: logged in as standard_user with only "Sauce Labs Backpack" in the cart
    await loginAs(page, "standard_user");
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    await expect(page.locator('[data-test="shopping-cart-badge"]')).toHaveText("1");

    // Step 1: Open the cart and click Checkout
    await page.locator('[data-test="shopping-cart-link"]').click();
    await expect(page).toHaveURL(/cart/);
    await page.locator('[data-test="checkout"]').click();
    await expect(page).toHaveURL(/checkout-step-one/);
    await expect(page.locator('[data-test="title"]')).toHaveText("Checkout: Your Information");

    // Step 2: Fill in customer information and continue
    await page.locator('[data-test="firstName"]').fill("John");
    await page.locator('[data-test="lastName"]').fill("Doe");
    await page.locator('[data-test="postalCode"]').fill("12345");
    await page.locator('[data-test="continue"]').click();
    await expect(page).toHaveURL(/checkout-step-two/);
    await expect(page.locator('[data-test="title"]')).toHaveText("Checkout: Overview");

    // Step 3: Item total
    await expect(page.locator('[data-test="subtotal-label"]')).toHaveText("Item total: $29.99");

    // Step 4: Tax
    await expect(page.locator('[data-test="tax-label"]')).toHaveText("Tax: $2.40");

    // Step 5: Total
    await expect(page.locator('[data-test="total-label"]')).toHaveText("Total: $35.39");
  });
});

